/**
 * apps/api/src/user-accounts/password.ts -- unit `ua-credentials`, spec UA-10 (hashing) and UA-11 (timing).
 *
 * argon2id (D-206 approved the `argon2` dependency), OWASP Password Storage Cheat Sheet first-choice
 * parameters: m = 19 MiB (19456 KiB), t = 2 iterations, p = 1 lane, version 0x13, 16-byte random salt and a
 * 32-byte tag generated by the library. The stored value is the PHC string, so the parameters travel with the
 * hash and can be raised later: `needsRehash` is true for anything weaker than the constants below, for
 * another algorithm and for an older version (the login path rehashes after a successful verify).
 *
 * The module surface is exactly hash / verify / needsRehash. Passwords are NFKC-normalised first, so the
 * composed and decomposed spelling of one passphrase are one password. verify() compares inside libargon2
 * (constant-time tag comparison) and never throws: a malformed stored hash is `false`. Passing no stored
 * hash (an unknown account) still runs a full argon2id verify against a per-process random dummy hash, so
 * "unknown email" and "wrong password" cost the same (UA-11).
 */
import { randomBytes } from "node:crypto";
import argon2 from "argon2";
import { hasLoneSurrogate } from "./email.js";
import { normalizePassword, passwordLength, PASSWORD_MAX } from "./password-policy.js";

export const PASSWORD_HASH_PARAMS = Object.freeze({ memoryCost: 19456, timeCost: 2, parallelism: 1, version: 19 });
const OPTIONS = { type: argon2.argon2id, ...PASSWORD_HASH_PARAMS } as const;
// The library writes the parameters as m,p,t while the PHC document lists m,t,p: parse by key so either order reads the same.
const PHC = /^\$argon2id\$v=(\d+)\$([mtp]=\d+(?:,[mtp]=\d+){2})\$[A-Za-z0-9+/]+\$[A-Za-z0-9+/]+$/;

/** The 1..128-character check on the normalised form; returns it, or null when out of range. */
function usable(password: unknown): string | null {
  if (typeof password !== "string" || password.length > PASSWORD_MAX * 4 || hasLoneSurrogate(password)) return null;
  const normalized = normalizePassword(password);
  const length = passwordLength(normalized);
  return length >= 1 && length <= PASSWORD_MAX ? normalized : null;
}

export async function hash(password: string): Promise<string> {
  if (typeof password !== "string") throw new TypeError("password must be a string");
  const normalized = usable(password);
  if (normalized === null) throw new RangeError(`password must be 1..${PASSWORD_MAX} well-formed characters`);
  return argon2.hash(normalized, OPTIONS);
}

let dummy: Promise<string> | null = null;
function dummyHash(): Promise<string> {
  // Random plaintext that nobody holds, so no caller-supplied password can ever match it.
  dummy ??= argon2.hash(randomBytes(32).toString("base64url"), OPTIONS);
  return dummy;
}

/** True only when `password` matches `storedHash`. A null/undefined/malformed hash yields false after a full dummy verify. */
export async function verify(storedHash: string | null | undefined, password: string): Promise<boolean> {
  const normalized = usable(password);
  if (normalized === null) return false;
  if (typeof storedHash === "string" && PHC.test(storedHash)) {
    try { return await argon2.verify(storedHash, normalized); } catch { return false; }
  }
  try { await argon2.verify(await dummyHash(), normalized); } catch { /* cost parity only */ }
  return false;
}

/** True when the stored hash is not argon2id v19 at (at least) the current parameters. */
export function needsRehash(storedHash: string): boolean {
  const m = typeof storedHash === "string" ? PHC.exec(storedHash) : null;
  if (!m) return true;
  const params = new Map(m[2]!.split(",").map((kv) => [kv[0]!, Number(kv.slice(2))] as const));
  const [mem, t, par] = [params.get("m"), params.get("t"), params.get("p")];
  if (mem === undefined || t === undefined || par === undefined || params.size !== 3) return true;
  return Number(m[1]) !== PASSWORD_HASH_PARAMS.version || mem < PASSWORD_HASH_PARAMS.memoryCost || t < PASSWORD_HASH_PARAMS.timeCost || par < PASSWORD_HASH_PARAMS.parallelism;
}
